  auto properties=decodeAseprite(linkedFixture(4,forward,true));check(properties.timeline.cels.size()==4,"distinct property chain count");for(unsigned fi=0;fi<4;++fi){const auto& cel=properties.timeline.cels[fi];check(cel.surface&&cel.surface->offsetX==int(fi)&&cel.surface->pixels[0]==0xff123456,"linked per-frame position rasterized");check(cel.opacity==double(128+fi)/255&&cel.zIndex==int(fi%3),"linked per-frame opacity and z retained");}
  auto d=documentFromAseprite(std::move(properties));auto round=documentFromAseprite(decodeAseprite(encodeAseprite(d)));for(unsigned fi=0;fi<4;++fi)check(compositeNormalRegion(d.timeline(),d.timeline().state().frames[fi].id,{0,0,4,2})==compositeNormalRegion(round.timeline(),round.timeline().state().frames[fi].id,{0,0,4,2}),"distinct property chain appearance roundtrip");
  for(bool missing:{false,true}){bool rejected=false;try{decodeAseprite(linkedFixture(12000,forward,false,!missing,missing));}catch(const std::exception&){rejected=true;}check(rejected,"long cyclic or missing link remains rejected");}
