 for(unsigned bits=0;bits<8;++bits){auto value=((bits&1)?0x80000000u:0)|((bits&2)?0x40000000u:0)|((bits&4)?0x20000000u:0);auto doc=documentFromAseprite(decodeAseprite(embeddedTileFixture(0,value)));std::vector<timeline::Pixel> expected(4);for(unsigned y=0;y<2;++y)for(unsigned x=0;x<2;++x){unsigned sx=bits&1?1-x:x,sy=bits&2?1-y:y;if(bits&4)std::swap(sx,sy);expected[y*2+x]=base[sy*2+sx];}check(doc.layer().kind.empty()&&doc.timeline().state().tilesets.empty()&&doc.canvasPixels()==expected,"embedded tile eight flip combinations rasterized");auto round=documentFromAseprite(decodeAseprite(encodeAseprite(doc)));check(round.canvasPixels()==expected,"embedded tile raster ASE roundtrip");doc.beginStroke({0,0},0xff123456);check(doc.commitStroke(),"embedded tile imported raster editable");doc.undo();check(doc.canvasPixels()==expected,"embedded raster undo");doc.redo();check(doc.canvasPixels()[0]==0xff123456,"embedded raster redo");auto native=project::prepareEditableImport(project::readProjectManifest(project::encodeEditableProject(doc).bytes));check(native.timeline.cels.front().surface->pixels==doc.canvasPixels(),"edited embedded raster native save reopen");}
 for(auto pair:{std::pair<unsigned,unsigned>{0,0xffffffffu},{4,0}})check(documentFromAseprite(decodeAseprite(embeddedTileFixture(pair.first,pair.second))).canvasPixels()==std::vector<timeline::Pixel>(4),"embedded old and new empty tile values");
 for(auto value:{1u,7u}){bool rejected=false;try{decodeAseprite(embeddedTileFixture(0,value));}catch(const std::exception&){rejected=true;}check(rejected,"embedded tile invalid index rejected");}bool rejected=false;try{decodeAseprite(embeddedTileFixture(0,0,32,1,false));}catch(const std::exception&){rejected=true;}check(rejected,"external tileset requires embedded data");
