  auto before=capture();check(before.timeline().state().cels.size()==count&&before.frame().id==frame&&before.layer().id==layer,"sparse worker snapshot preserves absent active slot");check(decodeAseprite(encodeAseprite(before)).timeline.cels.size()==count,"snapshot export preserves sparse slots");
  check(project::readProjectManifest(project::encodeEditableProject(before).bytes).cels.size()==count,"sparse unedited snapshot supports native save");
  DocumentSnapshot staleGeometry(d);
